251	    }
252	    if (id === astronautId) return ABOUT_DEFAULT_SCENE_STATE.astronaut;
253	    if (id === terrianId) return ABOUT_DEFAULT_SCENE_STATE.terrian;
254	    return ABOUT_DEFAULT_SCENE_STATE.background;
255	  }
