498	    if (!sampled) return;
499	    const [left, right, t] = sampled;
500	    const keys = this._profileKeys;
501	    for (let i = 0; i < keys.length; i += 1) {
502	      const key = keys[i];
503	      const leftValue = left.values[key];
504	      const rightValue = right.values[key];
505	      if (
506	        !Number.isFinite(leftValue as number) &&
507	        !Number.isFinite(rightValue as number)
